// Category B — a personal value shown masked, with a way to reveal it: 「010-****-1234」 and an eye
// Button. A POS shows customer phone numbers this way in its CRM and booking screens, as a dashboard
// does: the reveal asks for the staff PIN and then shows the number for a while.
//
// Masking here is a privacy rule, not a format, so the full value never reaches the DOM while masked:
// the component receives `masked` (made with `maskPhone` or the product's own pattern) and, only once
// the person may see it, `revealed`. The reveal itself (a PIN, a permission check, a timer) is the
// consumer's: `onReveal` asks for it, and `onHide` puts the mask back.
//
// The masked form is read with `maskedLabel` in place of its asterisks, which a screen reader would
// otherwise read one by one ("star star star star").
//
// Reveal and hide are one mounted Button whose label and glyph swap, so a PIN dialog opened from it
// returns focus to a control that still exists. Each action comes with its name, enforced by the types.
import { Eye, EyeOff } from "./icons";
import type { Ref } from "react";
import { Button } from "./Button";
import "./MaskedText.css";

export { maskPhone } from "./maskPhone";

export interface MaskedTextBaseProps {
  /**
   * Size axis: the type rung and the reveal Button.
   *
   * @default "medium"
   */
  size?: "small" | "medium" | "large";
  /** The value as shown while masked, e.g. "010-****-5678". */
  masked: string;
  /** Read in place of the masked form, e.g. "010 가운데 4자리 가림 5678". */
  maskedLabel: string;
  /** The full value, passed only once it may be shown. While set, it shows instead of `masked`. */
  revealed?: string;
}

export type MaskedTextProps = MaskedTextBaseProps &
  (
    | {
        /** Asks to reveal the value, e.g. by opening a PIN dialog. Without it there is no reveal. */
        onReveal: () => void;
        /** Accessible name of the reveal action, e.g. "전화번호 보기". */
        revealLabel: string;
      }
    | { onReveal?: undefined; revealLabel?: undefined }
  ) &
  (
    | {
        /** Masks the value again. */
        onHide: () => void;
        /** Accessible name of the hide action, e.g. "전화번호 가리기". */
        hideLabel: string;
      }
    | { onHide?: undefined; hideLabel?: undefined }
  ) & {
    /** Additional class (optional). sd-masked-text is always preserved. */
    className?: string;
    /** Forwarded to the root element. */
    ref?: Ref<HTMLSpanElement>;
  };

export function MaskedText({
  size = "medium",
  masked,
  maskedLabel,
  revealed,
  onReveal,
  revealLabel,
  onHide,
  hideLabel,
  className,
  ref,
}: MaskedTextProps) {
  const shown = revealed !== undefined;
  // The pairs are enforced by the types, so a handler always comes with its label.
  // With reveal only, the Button stays mounted and focusable once shown, marked aria-disabled with no
  // press handler, so focus stays put and a PIN dialog can return focus to it.
  const action = shown
    ? onHide
      ? { label: hideLabel as string, onPress: onHide }
      : onReveal && { label: revealLabel as string, onPress: undefined }
    : onReveal && { label: revealLabel as string, onPress: onReveal };
  return (
    <span ref={ref} className={className ? `sd-masked-text ${className}` : "sd-masked-text"}>
      {shown ? (
        <span className={`sd-masked-text__value sd-type-body-${size}`}>{revealed}</span>
      ) : (
        <span className={`sd-masked-text__value sd-type-body-${size}`}>
          <span aria-hidden="true">{masked}</span>
          <span className="sd-visually-hidden">{maskedLabel}</span>
        </span>
      )}
      {action && (
        <Button isIconOnly variant="ghost" size={size} aria-label={action.label} aria-disabled={action.onPress ? undefined : true} onPress={action.onPress}>
          {shown ? <EyeOff aria-hidden size="1em" /> : <Eye aria-hidden size="1em" />}
        </Button>
      )}
    </span>
  );
}

/* The value and its eye Button on one line. The value keeps its digits aligned while it switches
   between the masked and the full form. */
.sd-masked-text {
  display: inline-flex;
  align-items: center;
  gap: var(--sd-masked-text-gap);
}

.sd-masked-text__value {
  color: var(--sd-masked-text-foreground);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/**
 * Masks a Korean mobile number (01X, 10 or 11 digits) to its first three and last four digits:
 * "01012345678" → "010-****-5678". Any other number (a landline groups differently) keeps only its
 * last four digits: "0212345678" → "******5678".
 */
export function maskPhone(digits: string): string {
  const d = digits.replace(/\D/g, "");
  if (/^01\d{8,9}$/.test(d)) return `${d.slice(0, 3)}-${"*".repeat(d.length - 7)}-${d.slice(-4)}`;
  return d.length > 4 ? "*".repeat(d.length - 4) + d.slice(-4) : "*".repeat(d.length);
}
